  "source": "def investigate(context, acquire):
    actions = context["actions"]
    committed_ids = set()
    committed_seq = 0
    in_tx = False
    tx_ids = set()
    tx_seq = 0
    for action in actions:
        op = action["op"]
        if op == "begin":
            in_tx = True
            tx_ids = set(committed_ids)
            tx_seq = committed_seq
        elif op == "commit":
            committed_ids = tx_ids
            committed_seq = tx_seq
            in_tx = False
            tx_ids = set()
        elif op == "rollback":
            in_tx = False
            tx_ids = set()
        elif op == "put":
            id = action["id"]
            if in_tx:
                tx_ids.add(id)
                if id > tx_seq:
                    tx_seq = id
            else:
                committed_ids.add(id)
                if id > committed_seq:
                    committed_seq = id
        elif op == "delete":
            id = action["id"]
            if in_tx:
                tx_ids.discard(id)
            else:
                committed_ids.discard(id)
    if in_tx:
        ids = tx_ids
        seq = tx_seq
    else:
        ids = committed_ids
        seq = committed_seq
    m = 0
    for x in ids:
        if x > m:
            m = x
    if seq > m:
        m = seq
    return m + 1",
